@props(['events'=>[],'title'=>'Examination calendar'])
<x-card :title="$title" description="Dates from the authorized records shown on this page"><div x-data="examCalendar(@js($events))"><div class="calendar-toolbar"><div class="page-actions"><button class="icon-button" type="button" @click="move(-1)" aria-label="Previous period"><x-icon name="chevron" class="rotate-180" :size="16"/></button><strong x-text="heading"></strong><button class="icon-button" type="button" @click="move(1)" aria-label="Next period"><x-icon name="chevron" :size="16"/></button></div><div class="page-actions"><button class="btn btn-secondary btn-small" type="button" @click="today()">Today</button><button class="btn btn-secondary btn-small" type="button" @click="mode='week'" :aria-pressed="mode==='week'">Week</button><button class="btn btn-secondary btn-small" type="button" @click="mode='month'" :aria-pressed="mode==='month'">Month</button></div></div><div class="calendar-wrap"><div class="calendar-grid"><template x-for="day in ['Mon','Tue','Wed','Thu','Fri','Sat','Sun']"><div class="calendar-weekday" x-text="day"></div></template><template x-for="day in days" :key="day.key"><div class="calendar-cell" :class="{'is-today':day.today}"><span class="day" x-text="day.number"></span><template x-for="event in day.events" :key="event.id"><button type="button" class="calendar-event" :data-tone="event.title.charCodeAt(event.title.length-1)%4" :class="{'is-conflict':event.conflict}" @click="selected=event;$refs.detail.showModal()"><strong x-text="event.title"></strong><br><span x-text="event.detail"></span></button></template></div></template></div></div><dialog x-ref="detail" class="app-dialog drawer-dialog" aria-label="Calendar event details"><div class="dialog-head"><h2 x-text="selected?.title"></h2><button type="button" class="icon-button" @click="$refs.detail.close()" aria-label="Close event"><x-icon name="close"/></button></div><p x-text="selected?.detail"></p><p class="muted" x-text="selected?.date"></p><p class="callout callout-danger" x-show="selected?.conflict">Overlapping entries share this room. Review the scheduling form below.</p></dialog></div></x-card>
